package com.togglebuttons;

import java.util.ArrayList;
import java.util.List;

import lombok.Data;

// Defines 1 clickable "button" object's settings
@Data
class ToggleButtonsButton
{
	static final int DEFAULT_WIDTH = 40;
	static final int DEFAULT_HEIGHT = 40;
	static final int MAX_TARGETS = 50;
	static final int MAX_BUTTONS = 100;

	private String id;
	private String name = "Button";
	private int iconItemId = -1;
	// Absolute path to a local image file; takes priority over iconItemId
	private String iconImagePath;
	private int width = DEFAULT_WIDTH;
	private int height = DEFAULT_HEIGHT;
	private boolean resizable;
	private int buttonColor = ToggleButtonsStyle.DEFAULT_BUTTON_COLOR;
	private int pressedColor = ToggleButtonsStyle.DEFAULT_PRESSED_COLOR;
	private ToggleButtonsShape shape = ToggleButtonsShape.ROUNDED_RECTANGLE;
	private boolean toggleWhileHeld;
	private List<ToggleButtonsTarget> targets = new ArrayList<>();
}

package com.togglebuttons;

/*
* Holds the logic for the array of configured "button" objects
*/

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;

import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

import javax.inject.Inject;
import javax.inject.Singleton;

import lombok.extern.slf4j.Slf4j;

import net.runelite.client.config.ConfigManager;

@Slf4j
@Singleton
class ToggleButtonsButtonStore
{
	static final String CONFIG_GROUP = "togglebuttons";
	static final String BUTTONS_KEY = "buttons";
	private static final Type BUTTON_LIST_TYPE = new TypeToken<List<ToggleButtonsButton>>()
	{
	}.getType();

	private final ConfigManager configManager;
	private final Gson gson;

	@Inject
	ToggleButtonsButtonStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	List<ToggleButtonsButton> getButtons()
	{
		final String json = configManager.getConfiguration(CONFIG_GROUP, BUTTONS_KEY);
		if (json == null || json.isEmpty())
		{
			return new ArrayList<>();
		}

		try
		{
			List<ToggleButtonsButton> buttons = gson.fromJson(json, BUTTON_LIST_TYPE);
			if (buttons == null)
			{
				return new ArrayList<>();
			}
			if (buttons.size() > ToggleButtonsButton.MAX_BUTTONS)
			{
				log.warn("{} buttons stored; truncating to the maximum of {}",
					buttons.size(), ToggleButtonsButton.MAX_BUTTONS);
				buttons = new ArrayList<>(buttons.subList(0, ToggleButtonsButton.MAX_BUTTONS));
			}
			buttons.forEach(this::normalize);
			return buttons;
		}
		catch (JsonSyntaxException ex)
		{
			log.warn("Failed to parse stored buttons", ex);
			return new ArrayList<>();
		}
	}

	void setButtons(List<ToggleButtonsButton> buttons)
	{
		configManager.setConfiguration(CONFIG_GROUP, BUTTONS_KEY, gson.toJson(buttons, BUTTON_LIST_TYPE));
	}

	// Returns null when the maximum number of buttons has been reached
	ToggleButtonsButton createButton()
	{
		final List<ToggleButtonsButton> buttons = getButtons();
		if (buttons.size() >= ToggleButtonsButton.MAX_BUTTONS)
		{
			log.debug("Cannot create button; already at the maximum of {}", ToggleButtonsButton.MAX_BUTTONS);
			return null;
		}

		final ToggleButtonsButton button = new ToggleButtonsButton();
		button.setId(UUID.randomUUID().toString());
		button.setName("Button " + (buttons.size() + 1));
		buttons.add(button);
		setButtons(buttons);
		return button;
	}

	private void normalize(ToggleButtonsButton button)
	{
		if (button.getId() == null || button.getId().isEmpty())
		{
			button.setId(UUID.randomUUID().toString());
		}
		if (button.getName() == null)
		{
			button.setName("Button");
		}
		if (button.getTargets() == null)
		{
			button.setTargets(new ArrayList<>());
		}
		if (button.getTargets().size() > ToggleButtonsButton.MAX_TARGETS)
		{
			log.warn("Button '{}' has {} targets; truncating to the maximum of {}",
				button.getName(), button.getTargets().size(), ToggleButtonsButton.MAX_TARGETS);
			button.setTargets(new ArrayList<>(button.getTargets().subList(0, ToggleButtonsButton.MAX_TARGETS)));
		}
		if (button.getShape() == null)
		{
			button.setShape(ToggleButtonsShape.ROUNDED_RECTANGLE);
		}
		if (button.getWidth() < 16)
		{
			button.setWidth(ToggleButtonsButton.DEFAULT_WIDTH);
		}
		if (button.getHeight() < 16)
		{
			button.setHeight(ToggleButtonsButton.DEFAULT_HEIGHT);
		}
	}
}

package com.togglebuttons;

/*
* Config items for the plugin (not panel) settings
*/

import net.runelite.client.config.Config;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("togglebuttons")
public interface ToggleButtonsConfig extends Config
{
	@ConfigItem(
		keyName = "showButtons",
		name = "Show buttons",
		description = "Whether the buttons are drawn on screen",
		position = 0
	)
	default boolean showButtons()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hotkey",
		name = "Show/hide buttons hotkey",
		description = "Keybind that shows or hides all buttons",
		position = 1
	)
	default Keybind hotkey()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "sidebarClickMode",
		name = "Sidebar left click",
		description = "What clicking a button in the sidebar does.<br>"
			+ "Open editor: opens the button's settings.<br>"
			+ "Execute button: activates the button as if clicked<br>"
			+ "in the game view; editing moves to right click.",
		position = 2
	)
	default ToggleButtonsSidebarClickMode sidebarClickMode()
	{
		return ToggleButtonsSidebarClickMode.EDIT;
	}
}

package com.togglebuttons;

/*
* Contains helper logic for performing an icon search against the game's cached itemIds
*/

import java.util.function.IntConsumer;

import javax.inject.Inject;
import javax.inject.Singleton;

import lombok.extern.slf4j.Slf4j;

import net.runelite.api.Client;
import net.runelite.api.GameState;

import net.runelite.client.callback.ClientThread;
//Library which handles the fancy ability to item search as seen in many popular plugins
import net.runelite.client.game.chatbox.ChatboxItemSearch;

@Slf4j
@Singleton
class ToggleButtonsIconSearch
{
	private final Client client;
	private final ClientThread clientThread;
	private final ChatboxItemSearch itemSearch;

	@Inject
	ToggleButtonsIconSearch(Client client, ClientThread clientThread, ChatboxItemSearch itemSearch)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.itemSearch = itemSearch;
	}

	void open(IntConsumer onSelected)
	{
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				log.debug("Cannot open icon search before logging in");
				return;
			}

			itemSearch
				.tooltipText("Search for a button icon")
				.onItemSelected(onSelected::accept)
				.build();
		});
	}
}

package com.togglebuttons;

/*
* Manages button icon images. When the user picks a file it is
* copied into .runelite/toggle-buttons/ and only ever read back
* from there, per hub file IO guidelines. A file image always
* takes priority over a searched item icon.
*/

import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import javax.imageio.ImageIO;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

@Slf4j
final class ToggleButtonsImageLoader
{
	static final File IMAGE_DIR = new File(RuneLite.RUNELITE_DIR, "toggle-buttons");

	// Icons are drawn at button size; larger images are scaled down on import
	private static final int MAX_DIMENSION = 512;

	private ToggleButtonsImageLoader()
	{
	}

	// Imports a user-chosen image into the plugin directory and returns the
	// stored file's name for persistence, or null if the file is not a
	// readable image. Oversized images are scaled down rather than rejected.
	static String store(String buttonId, File chosen)
	{
		BufferedImage image = read(chosen);
		if (image == null)
		{
			return null;
		}

		if (image.getWidth() > MAX_DIMENSION || image.getHeight() > MAX_DIMENSION)
		{
			log.debug("Downscaling button image {} ({}x{}) to fit {}x{}",
				chosen, image.getWidth(), image.getHeight(), MAX_DIMENSION, MAX_DIMENSION);
			image = downscale(image);
		}

		if (!IMAGE_DIR.exists() && !IMAGE_DIR.mkdirs())
		{
			log.warn("Failed to create image directory {}", IMAGE_DIR);
			return null;
		}

		// One image per button; always stored as png since we re-encode
		final File destination = new File(IMAGE_DIR, buttonId + ".png");
		try
		{
			ImageIO.write(image, "png", destination);
			return destination.getName();
		}
		catch (IOException ex)
		{
			log.warn("Failed to write button image to {}", destination, ex);
			return null;
		}
	}

	// Scales an image down to fit MAX_DIMENSION, preserving aspect ratio
	private static BufferedImage downscale(BufferedImage image)
	{
		final double scale = (double) MAX_DIMENSION / Math.max(image.getWidth(), image.getHeight());
		final int width = Math.max(1, (int) (image.getWidth() * scale));
		final int height = Math.max(1, (int) (image.getHeight() * scale));

		final BufferedImage scaled = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = scaled.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.drawImage(image, 0, 0, width, height, null);
		g.dispose();
		return scaled;
	}

	// Loads a stored image by the file name persisted in the button config;
	// returns null when unset, missing, or unreadable
	static BufferedImage load(String storedName)
	{
		if (storedName == null || storedName.isEmpty())
		{
			return null;
		}

		// Stored names are generated by store(); reject anything path-like
		final File file = new File(IMAGE_DIR, new File(storedName).getName());
		if (!file.isFile())
		{
			log.debug("Button icon image not found: {}", file);
			return null;
		}
		return read(file);
	}

	// Deletes a stored image when its button no longer uses it
	static void delete(String storedName)
	{
		if (storedName == null || storedName.isEmpty())
		{
			return;
		}

		final File file = new File(IMAGE_DIR, new File(storedName).getName());
		if (file.isFile() && !file.delete())
		{
			log.debug("Failed to delete button image {}", file);
		}
	}

	private static BufferedImage read(File file)
	{
		if (!file.isFile())
		{
			return null;
		}

		try
		{
			final BufferedImage image = ImageIO.read(file);
			if (image == null)
			{
				log.warn("File is not a readable image: {}", file);
			}
			return image;
		}
		catch (IOException ex)
		{
			log.warn("Failed to read button icon image: {}", file, ex);
			return null;
		}
	}
}

package com.togglebuttons;

/*
* Handles left mouse clicks on button overlays,
* triggering their plugin toggle states
* 1 click should always be 1 toggle actions, not simulation
*/

import java.awt.event.MouseEvent;

import java.util.Collection;
import java.util.Collections;
import java.util.function.Supplier;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;

import lombok.Setter;
import lombok.extern.slf4j.Slf4j;

import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;

@Slf4j
@Singleton
class ToggleButtonsMouseBehavior extends MouseAdapter
{
	private final MouseManager mouseManager;
	private final ToggleButtonsConfig config;
	private final ToggleButtonsToggle toggle;

	@Setter
	private Supplier<Collection<ToggleButtonsOverlay>> overlaySupplier = Collections::emptyList;

	@Inject
	ToggleButtonsMouseBehavior(MouseManager mouseManager, ToggleButtonsConfig config, ToggleButtonsToggle toggle)
	{
		this.mouseManager = mouseManager;
		this.config = config;
		this.toggle = toggle;
	}

	void startUp()
	{
		mouseManager.registerMouseListener(this);
	}

	void shutDown()
	{
		mouseManager.unregisterMouseListener(this);
	}

	@Override
	public MouseEvent mousePressed(MouseEvent e)
	{
		if (!config.showButtons() ||
			!SwingUtilities.isLeftMouseButton(e) ||
			e.isAltDown())
		{
			return e;
		}

		for (ToggleButtonsOverlay overlay : overlaySupplier.get())
		{
			if (overlay.getBounds().contains(e.getPoint()))
			{
				overlay.setPressed(true);
				toggle.press(overlay.getButton());
				e.consume();
				break;
			}
		}
		return e;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent e)
	{
		if (SwingUtilities.isLeftMouseButton(e))
		{
			toggle.release();

			for (ToggleButtonsOverlay overlay : overlaySupplier.get())
			{
				overlay.setPressed(false);
			}
		}
		return e;
	}
}

package com.togglebuttons;

/*
* Game window button overlay rendering logic
*/

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.Area;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.Rectangle2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;

import lombok.Getter;
import lombok.Setter;

import net.runelite.api.MenuAction;

import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayMenuEntry;
import net.runelite.client.ui.overlay.OverlayPosition;

public class ToggleButtonsOverlay extends Overlay
{
	private static final int MIN_SIZE = 16;

	private final ToggleButtonsConfig config;

	@Getter
	private final ToggleButtonsButton button;

	@Getter
	@Setter
	private volatile boolean pressed;

	@Setter
	private volatile BufferedImage icon;

	ToggleButtonsOverlay(ToggleButtonsConfig config, ToggleButtonsButton button)
	{
		this.config = config;
		this.button = button;
		setPosition(OverlayPosition.TOP_LEFT);
		setMovable(true);
		getMenuEntries().add(new OverlayMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG, "Configure", "Toggle Buttons"));
	}

	@Override
	public String getName()
	{
		return "toggleButtonsButton_" + button.getId();
	}

	// Mostly borrowed from prior art in
	// https://github.com/StationEarthxo/Stations-Cozy-Carts/blob/master/src/main/java/com/cartmount/CartToggleOverlay.java
	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showButtons())
		{
			return null;
		}

		if (isResizable() != button.isResizable())
		{
			setResizable(button.isResizable());
		}

		int width = button.getWidth();
		int height = button.getHeight();

		final Dimension preferred = getPreferredSize();
		if (button.isResizable() && preferred != null)
		{
			width = Math.max(MIN_SIZE, preferred.width);
			height = Math.max(MIN_SIZE, preferred.height);
		}

		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setColor(new Color(pressed ? button.getPressedColor() : button.getButtonColor(), true));
		graphics.fill(buildShape(button.getShape(), width, height));

		final BufferedImage img = icon;
		if (img != null)
		{
			final double scale = Math.min((double) width / img.getWidth(), (double) height / img.getHeight());
			final int iw = (int) (img.getWidth() * scale);
			final int ih = (int) (img.getHeight() * scale);
			graphics.drawImage(img, (width - iw) / 2, (height - ih) / 2, iw, ih, null);
		}

		return new Dimension(width, height);
	}

	private static Shape buildShape(ToggleButtonsShape shape, int w, int h)
	{
		switch (shape)
		{
		case SQUARE:
			return new Rectangle2D.Double(0, 0, w, h);
		case CIRCLE:
			final int d = Math.min(w, h);
			return new Ellipse2D.Double((w - d) / 2.0, (h - d) / 2.0, d, d);
		case DIAMOND:
			return polygon(new double[] { w / 2.0, w, w / 2.0, 0 }, new double[] { 0, h / 2.0, h, h / 2.0 });
		case TRIANGLE_UP:
			return polygon(new double[] { w / 2.0, w, 0 }, new double[] { 0, h, h });
		case TRIANGLE_DOWN:
			return polygon(new double[] { 0, w, w / 2.0 }, new double[] { 0, 0, h });
		case HEXAGON:
			return polygon(
				new double[] { w * 0.25, w * 0.75, w, w * 0.75, w * 0.25, 0 },
				new double[] { 0, 0, h / 2.0, h, h, h / 2.0 });
		case OCTAGON:
			final double c = Math.min(w, h) / 3.0;
			return polygon(
				new double[] { c, w - c, w, w, w - c, c, 0, 0 },
				new double[] { 0, 0, c, h - c, h, h, h - c, c });
		case PARALLELOGRAM:
			final double skew = w / 4.0;
			return polygon(new double[] { skew, w, w - skew, 0 }, new double[] { 0, 0, h, h });
		case STAR:
			return star(w, h);
		case GEAR:
			return gear(w, h);
		case ROUNDED_RECTANGLE:
		default:
			final int arc = Math.min(w, h) / 4;
			return new RoundRectangle2D.Double(0, 0, w, h, arc, arc);
		}
	}

	private static Shape polygon(double[] xs, double[] ys)
	{
		final Path2D.Double path = new Path2D.Double();
		path.moveTo(xs[0], ys[0]);
		for (int i = 1; i < xs.length; i++)
		{
			path.lineTo(xs[i], ys[i]);
		}
		path.closePath();
		return path;
	}

	// 5-point star scaled to the button bounds
	private static Shape star(int w, int h)
	{
		final double cx = w / 2.0;
		final double cy = h / 2.0;
		final double outerX = w / 2.0;
		final double outerY = h / 2.0;
		final double innerX = outerX * 0.4;
		final double innerY = outerY * 0.4;

		final Path2D.Double path = new Path2D.Double();
		for (int i = 0; i < 10; i++)
		{
			final double angle = -Math.PI / 2 + i * Math.PI / 5;
			final double rx = (i % 2 == 0) ? outerX : innerX;
			final double ry = (i % 2 == 0) ? outerY : innerY;
			final double x = cx + rx * Math.cos(angle);
			final double y = cy + ry * Math.sin(angle);
			if (i == 0)
			{
				path.moveTo(x, y);
			}
			else
			{
				path.lineTo(x, y);
			}
		}
		path.closePath();
		return path;
	}

	// Circular gear with 8 teeth scaled to the button bounds
	private static Shape gear(int w, int h)
	{
		final double cx = w / 2.0;
		final double cy = h / 2.0;
		final double r = Math.min(w, h) / 2.0;
		final double bodyRadius = r * 0.78;
		final double toothWidth = r * 0.35;

		final Area area = new Area(new Ellipse2D.Double(cx - bodyRadius, cy - bodyRadius, bodyRadius * 2, bodyRadius * 2));
		for (int i = 0; i < 8; i++)
		{
			final java.awt.geom.AffineTransform rotate = java.awt.geom.AffineTransform.getRotateInstance(i * Math.PI / 4, cx, cy);
			final Shape tooth = rotate.createTransformedShape(
				new Rectangle2D.Double(cx - toothWidth / 2, cy - r, toothWidth, r));
			area.add(new Area(tooth));
		}
		return area;
	}
}

package com.togglebuttons;

// mentally I'm considering this "main"

import com.google.inject.Provides;

import java.awt.image.BufferedImage;
import java.util.LinkedHashMap;
import java.util.Map;

import javax.inject.Inject;
import javax.swing.SwingUtilities;

import lombok.extern.slf4j.Slf4j;
import lombok.Getter;
import lombok.Setter;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;

import net.runelite.client.game.ItemManager;

import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Toggle Buttons",
	description = "Runelite plugin for creating clickable buttons that toggle other plugins",
	tags = {
		"button", "buttons", "toggle", "click", "peek", "hide", "unhide"
	}
)

public class ToggleButtonsPlugin extends Plugin
{
	// Local API injections
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private ToggleButtonsConfig config;
	@Inject
	private ItemManager itemManager;
	@Inject
	private ToggleButtonsButtonStore buttonStore;
	@Inject
	private ToggleButtonsMouseBehavior mouseBehavior;
	@Inject
	private ToggleButtonsVisibility visibility;
	@Inject
	private ClientToolbar clientToolbar;
	@Inject
	private ToggleButtonsPluginPanel panel;

	// Local Vars
	private final Map<String, ToggleButtonsOverlay> overlays = new LinkedHashMap<>();
	private NavigationButton navButton;

	@Setter
	@Getter
	private boolean navButtonIsSelected;

	@Override
	protected void startUp() throws Exception
	{
		rebuildOverlays();
		mouseBehavior.setOverlaySupplier(overlays::values);
		mouseBehavior.startUp();
		visibility.startUp();

		// Adds button to sidebar with icon
		final BufferedImage sidebarIcon = ImageUtil.loadImageResource(getClass(), "panel_icon.png");
		this.navButtonIsSelected = false;
		navButton = NavigationButton.builder()
			.tooltip("Toggle Buttons")
			.icon(sidebarIcon)
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		SwingUtilities.invokeLater(panel::rebuild);
		log.debug("Toggle Buttons started!");
	}

	@Override
	protected void shutDown() throws Exception
	{
		removeOverlays();
		mouseBehavior.shutDown();
		visibility.shutDown();
		clientToolbar.removeNavigation(navButton);
		log.debug("Toggle Buttons stopped!");
	}

	private void rebuildOverlays()
	{
		removeOverlays();
		for (ToggleButtonsButton button : buttonStore.getButtons())
		{
			final ToggleButtonsOverlay overlay = new ToggleButtonsOverlay(config, button);
			// A local image takes priority over a searched item icon; never both
			final java.awt.image.BufferedImage fileImage = ToggleButtonsImageLoader.load(button.getIconImagePath());
			if (fileImage != null)
			{
				overlay.setIcon(fileImage);
			}
			else if (button.getIconItemId() >= 0)
			{
				overlay.setIcon(itemManager.getImage(button.getIconItemId()));
			}
			overlays.put(button.getId(), overlay);
			overlayManager.add(overlay);
		}
	}

	private void removeOverlays()
	{
		for (ToggleButtonsOverlay overlay : overlays.values())
		{
			overlayManager.remove(overlay);
		}
		overlays.clear();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!"togglebuttons".equals(event.getGroup()))
		{
			return;
		}

		if (ToggleButtonsButtonStore.BUTTONS_KEY.equals(event.getKey()))
		{
			rebuildOverlays();
		}

		if ("sidebarClickMode".equals(event.getKey()))
		{
			SwingUtilities.invokeLater(panel::rebuild);
		}
	}

	@Provides
	ToggleButtonsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ToggleButtonsConfig.class);
	}
}

package com.togglebuttons;

/*
* Crafts the view of the plugin's sidebar panel,
* where buttons are managed in a grid and the
* selected button's settings are edited below it
* AKA, the file that made me realize why nobody learns java
* for UI work in 2026
*/

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;

import java.util.List;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JFileChooser;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.JScrollBar;
import javax.swing.JScrollPane;
import javax.swing.JSpinner;
